public partial class PhysicsBakeCacheOperations:RefCounted
{
    private const long MaxBytes=67108864,MaxRaw=268435456,MaxStream=4294967296,MaxChunk=16777216;private readonly ActorDataOperations _data=new();private static Settings Map(Resource owner,string key)=>owner.Get(key).AsGodotDictionary();private static GArray List(Resource owner,string key)=>owner.Get(key).AsGodotArray();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public string begin_stream(Resource owner,string directory){string root=ProjectSettings.GlobalizePath(directory).PathJoin("bake-"+_data.new_id()).SimplifyPath();owner.Set("storage_root",root);return DirAccess.MakeDirRecursiveAbsolute(root)!=Error.Ok?"Cannot create bake cache directory.":"";}
    public string digest(byte[] data)=>Convert.ToHexString(SHA256.HashData(data)).ToLowerInvariant();
    public Variant encode(Resource owner,Variant value,string key)
    {
        if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource resource){long instance=unchecked((long)resource.GetInstanceId());var indices=Map(owner,"resource_indices");if(!indices.ContainsKey(instance)){var resources=List(owner,"resources");indices[instance]=resources.Count;resources.Add(resource);long bytes=owner.Get("resource_bytes").AsInt64();if(ActorDataOperations.ScriptIs(resource,"res://Workspaces/ModelWorkspace/model_mesh.gd")){bytes+=resource.Get("vertices").AsVector3Array().Length*12L+resource.Get("materials").AsInt32Array().Length*4L;foreach(var face in resource.Get("faces").AsGodotArray())bytes+=face.AsInt32Array().Length*12L+64;}else if(resource is Mesh mesh){for(int i=0;i<mesh.GetSurfaceCount();i++)bytes+=GD.VarToBytes(mesh.SurfaceGetArrays(i)).Length;}else bytes+=1024;owner.Set("resource_bytes",bytes);}return new Settings{["@resource"]=indices[instance]};}if(value.VariantType==Variant.Type.Dictionary){var source=value.AsGodotDictionary();if(key=="destruction_geometry"){var identity=Get(source,"key",(long)GD.Hash(source));var indices=Map(owner,"record_indices");var records=List(owner,"records");if(!indices.ContainsKey(identity)){indices[identity]=records.Count;records.Add(encode(owner,value,"record"));}return new Settings{["@record"]=indices[identity]};}var result=new Settings();foreach(var entry in source)result[entry.Key]=encode(owner,entry.Value,entry.Key.ToString());return result;}if(value.VariantType==Variant.Type.Array){var result=new GArray();foreach(var item in value.AsGodotArray())result.Add(encode(owner,item,""));return result;}return value;
    }
    public Variant decode(Resource owner,Variant value){if(value.VariantType==Variant.Type.Dictionary){var source=value.AsGodotDictionary();if(source.ContainsKey("@resource"))return List(owner,"resources")[source["@resource"].AsInt32()];if(source.ContainsKey("@record"))return decode(owner,List(owner,"records")[source["@record"].AsInt32()]);var result=new Settings();foreach(var entry in source)result[entry.Key]=decode(owner,entry.Value);return result;}if(value.VariantType==Variant.Type.Array){var result=new GArray();foreach(var item in value.AsGodotArray())result.Add(decode(owner,item));return result;}return value;}
    public string append(Resource owner,Settings frame){var encoded=encode(owner,frame,"");long size=GD.VarToBytes(encoded).Length+16L;if(size>MaxChunk)return "A single bake frame exceeds the 16 MiB chunk budget. Lower simulation resolution.";var pending=List(owner,"pending");if(pending.Count>0&&owner.Get("pending_bytes").AsInt64()+size>MaxChunk-1024){string error=flush(owner);if(error.Length>0)return error;}pending.Add(encoded);owner.Set("pending_bytes",owner.Get("pending_bytes").AsInt64()+size);owner.Set("count",owner.Get("count").AsInt64()+1);long resources=owner.Get("resource_bytes").AsInt64();if(resources>MaxBytes||(owner.Get("storage_root").AsString().Length==0&&owner.Get("bytes").AsInt64()+resources>MaxBytes))return "Bake exceeds the 64 MiB resident geometry/data budget. Nothing was replaced.";return pending.Count>=32?flush(owner):"";}
    public string flush(Resource owner)
    {
        var pending=List(owner,"pending");if(pending.Count==0)return "";var raw=GD.VarToBytes(pending);long rawBytes=owner.Get("raw_bytes").AsInt64()+raw.Length;owner.Set("raw_bytes",rawBytes);if(raw.Length>MaxChunk)return "A bake chunk exceeds the 16 MiB resident chunk limit. Lower sample density.";string root=owner.Get("storage_root").AsString();if(rawBytes>(root.Length==0?MaxRaw:MaxStream))return "Bake exceeds its expanded-data storage budget.";var packed=GD.Compress(raw,Godot.FileAccess.CompressionMode.Zstd);long bytes=owner.Get("bytes").AsInt64()+packed.Length;owner.Set("bytes",bytes);if((root.Length==0&&bytes+owner.Get("resource_bytes").AsInt64()>MaxBytes)||bytes>MaxStream)return "Bake exceeds its storage budget. Nothing was replaced.";var chunks=List(owner,"chunks");var chunk=new Settings{["first"]=owner.Get("count").AsInt64()-pending.Count,["count"]=pending.Count,["raw_size"]=raw.Length,["sha256"]=digest(packed)};if(root.Length==0)chunk["data"]=packed;else{string path=root.PathJoin("chunk-"+chunks.Count.ToString("D6",System.Globalization.CultureInfo.InvariantCulture)+".bin");using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Write);if(file==null)return "Cannot write a bake chunk; previous bake preserved.";file.StoreBuffer(packed);file.Flush();var error=file.GetError();file.Close();List(owner,"owned_files").Add(path);if(error!=Error.Ok)return "Bake storage is full or unavailable.";chunk["file"]=path;}chunks.Add(chunk);pending.Clear();owner.Set("pending_bytes",0);return "";
    }
    public string finish_stream(Resource owner){string result=flush(owner);if(result.Length>0)return result;owner.Set("complete",true);string root=owner.Get("storage_root").AsString();if(root.Length>0){string path=root.PathJoin("cache.res");if(ResourceSaver.Save(owner,path)!=Error.Ok){owner.Set("complete",false);return "Cannot save bake manifest.";}List(owner,"owned_files").Add(path);}return "";}
    public void abort_stream(Resource owner){string root=owner.Get("storage_root").AsString();var files=List(owner,"owned_files");foreach(var value in files){string path=value.AsString();if(path.GetBaseDir()==root)DirAccess.RemoveAbsolute(path);}files.Clear();if(root.Length>0)DirAccess.RemoveAbsolute(root);}
    public byte[] packed_chunk(Resource owner,Settings chunk){var data=Get(chunk,"data",Array.Empty<byte>()).AsByteArray();if(chunk.ContainsKey("file")){string path=chunk["file"].AsString();using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);if(file==null){owner.Set("error","Missing bake chunk: "+path);return Array.Empty<byte>();}if(file.GetLength()>MaxChunk){owner.Set("error","Bake chunk is larger than the safety budget.");return Array.Empty<byte>();}data=file.GetBuffer((long)file.GetLength());}if(chunk.ContainsKey("sha256")&&digest(data)!=chunk["sha256"].AsString()){owner.Set("error","Bake chunk failed its integrity check.");return Array.Empty<byte>();}return data;}
    public Settings frame(Resource owner,int index){owner.Set("error","");index=Math.Min(Math.Max(index,0),Math.Max(0,owner.Get("count").AsInt32()-1));var chunks=List(owner,"chunks");int low=0,high=chunks.Count-1,chunkIndex=-1;while(low<=high){int middle=(low+high)/2;var candidate=chunks[middle].AsGodotDictionary();if(index<candidate["first"].AsInt64())high=middle-1;else if(index>=candidate["first"].AsInt64()+candidate["count"].AsInt64())low=middle+1;else{chunkIndex=middle;break;}}if(chunkIndex<0)return new Settings();var decoded=Map(owner,"decoded");if(!decoded.ContainsKey(chunkIndex)){var chunk=chunks[chunkIndex].AsGodotDictionary();long size=chunk["raw_size"].AsInt64();if(size<0||size>MaxChunk){owner.Set("error","Bake chunk has an invalid expanded size.");return new Settings();}var packed=packed_chunk(owner,chunk);if(packed.Length==0)return new Settings();var raw=GD.Decompress(packed,size,Godot.FileAccess.CompressionMode.Zstd);var frames=GD.BytesToVar(raw);if(frames.VariantType!=Variant.Type.Array){owner.Set("error","Bake chunk does not contain valid frame data.");return new Settings();}while(decoded.Count>=2)decoded.Remove(decoded.Keys.First());decoded[chunkIndex]=frames;}return decode(owner,decoded[chunkIndex].AsGodotArray()[index-chunks[chunkIndex].AsGodotDictionary()["first"].AsInt32()]).AsGodotDictionary();}
}
